// One item per document: uploaded files, plus the form fields and label text as virtual documents.
const v = $('Validate request').first().json;
const bins = $('Webhook POST /ai/analyses').first().binary || {};
const items = [];
const inline = (requirementId, fileName, text) => items.push({
  json: { requirementId, fileName },
  binary: { data: { data: Buffer.from(text, 'utf8').toString('base64'), mimeType: 'text/plain', fileName } },
});

const lines = Object.entries(v.fields).map(([k, val]) => `${k}: ${typeof val === 'object' ? JSON.stringify(val) : val}`);
if (lines.length) inline('application-form', 'application-form.txt', 'Application form\n' + lines.join('\n'));
if (v.labelText) inline('artwork', 'label-text.txt', 'Label text\n' + v.labelText);
for (const f of v.files) items.push({ json: { requirementId: f.requirementId, fileName: f.fileName }, binary: { data: bins[f.key] } });
return items;

function htmlToText(html) {
  return String(html)
    .replace(/<head[\s\S]*?<\/head>/gi, '')
    .replace(/<(script|style)[\s\S]*?<\/\1>/gi, '')
    .replace(/<br\s*\/?>|<\/(p|div|h[1-6]|li|tr)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&')
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function chunkText(text, size, overlap) {
  const out = [];
  let start = 0;
  while (start < text.length) {
    let end = Math.min(start + size, text.length);
    if (end < text.length) {
      const brk = Math.max(text.lastIndexOf('\n', end), text.lastIndexOf('. ', end));
      if (brk > start + size * 0.5) end = brk + 1;
    }
    const piece = text.slice(start, end).trim();
    if (piece) out.push(piece);
    if (end >= text.length) break;
    start = Math.max(end - overlap, start + 1);
  }
  return out;
}

// Tika returns XHTML; PDFs come back with one <div class="page"> per page.
function splitPages(html) {
  const parts = String(html).split(/<div class="page">/i);
  if (parts.length > 1) return parts.slice(1).map((p, i) => ({ page: i + 1, text: htmlToText(p) }));
  return [{ page: null, text: htmlToText(html) }];
}

const cfg = $('Validate request').first().json.config;
const docs = $('Prepare documents').all().map((i) => i.json);

const chunks = [];
const documents = [];
$input.all().forEach((item, i) => {
  const d = docs[i];
  let n = 0, pages = 0, characters = 0, truncated = false;
  for (const { page, text } of splitPages(item.json.data || '')) {
    if (page) pages = page;
    characters += text.length;
    for (const piece of chunkText(text, cfg.chunkSize, cfg.chunkOverlap)) {
      if (n >= cfg.maxChunksPerDocument) { truncated = true; break; }
      chunks.push({ id: 'S' + (chunks.length + 1), requirementId: d.requirementId, file: d.fileName, page, text: piece });
      n++;
    }
  }
  documents.push({ requirementId: d.requirementId, fileName: d.fileName, pages: pages || null, characters, chunks: n, truncated, noText: characters === 0 });
});
if (!chunks.length) throw new Error('No text could be extracted from the documents (scanned files without OCR?)');

const out = [];
for (let i = 0; i < chunks.length; i += cfg.embedBatch) {
  out.push({ json: { model: cfg.embedModel, input: chunks.slice(i, i + cfg.embedBatch).map((c) => c.text), ...(i === 0 ? { chunks, documents } : {}) } });
}
return out;

// Decide which rules to evaluate, and against which documents.
// A rule with requirement ids is checked only against those documents; without, against everything sent.
const v = $('Validate request').first().json;
const { documents } = $('Split into chunks').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.rule_code);
const provided = [...new Set(documents.filter((d) => d.chunks > 0).map((d) => d.requirementId))];

const evaluate = [], skipped = [];
for (const r of rows) {
  const wanted = (r.requirement_ids || []).filter((id) => /^[a-z0-9-]{1,40}$/.test(id));
  const use = wanted.length ? wanted.filter((id) => provided.includes(id)) : provided;
  const base = { ruleCode: r.rule_code, rule: r.rule_text, severity: r.severity, requirementIds: wanted, version: r.version };
  if (!use.length) skipped.push({ ...base, reason: `Not evaluated: no ${wanted.join(' or ')} document was sent` });
  else evaluate.push({ ...base, guidance: r.guidance, use });
}
return [{ json: { evaluate, skipped, model: v.config.embedModel, input: evaluate.map((r) => r.rule + (r.guidance ? '\n' + r.guidance : '')) } }];

function cosine(a, b) {
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) { dot += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i]; }
  return dot / (Math.sqrt(na) * Math.sqrt(nb) || 1);
}
const v = $('Validate request').first().json;
const { chunks } = $('Split into chunks').first().json;
const chunkVecs = $('Embed submission').all().flatMap((i) => i.json.embeddings);
const { evaluate } = $('Scope rules').first().json;
const ruleVecs = $input.first().json.embeddings;

// One item per rule: the best excerpts from the documents that rule applies to.
return evaluate.map((r, i) => {
  const evidence = chunks
    .map((c, j) => ({ c, j }))
    .filter(({ c }) => r.use.includes(c.requirementId))
    .map(({ c, j }) => ({ ...c, score: Math.round(cosine(ruleVecs[i], chunkVecs[j]) * 1000) / 1000 }))
    .sort((a, b) => b.score - a.score)
    .slice(0, v.config.topKEvidence);
  return {
    json: {
      ...r, evidence,
      ruleVec: '[' + ruleVecs[i].join(',') + ']',
      reqArray: `ARRAY[${r.use.map((id) => `'${id}'`).join(',')}]::text[]`,
    },
  };
});

// LLM request and response helpers, shared by every node that talks to the model.
// OpenAI uses strict JSON-schema output; Ollama uses its "format" option.
function strictSchema(s) {
  // OpenAI strict mode: every object lists all its properties as required and allows no others.
  if (s && s.type === 'object') return { ...s, additionalProperties: false, required: Object.keys(s.properties), properties: Object.fromEntries(Object.entries(s.properties).map(([k, v]) => [k, strictSchema(v)])) };
  if (s && s.type === 'array') return { ...s, items: strictSchema(s.items) };
  return s;
}
function llmRequest(config, system, user, schema, name) {
  const messages = [{ role: 'system', content: system }, { role: 'user', content: user }];
  if (config.llmProvider === 'openai') {
    return { model: config.llmModel, temperature: 0, messages, response_format: { type: 'json_schema', json_schema: { name, strict: true, schema: strictSchema(schema) } } };
  }
  return { model: config.llmModel, stream: false, format: schema, options: { temperature: 0, num_ctx: 8192 }, messages };
}
// Returns { data, error, tokens } from either provider's response item.
function llmResult(json) {
  if (json.error) return { data: null, error: String(json.error.message || json.error), tokens: 0 };
  const content = json.choices ? json.choices[0] && json.choices[0].message && json.choices[0].message.content : json.message && json.message.content;
  const tokens = json.usage ? json.usage.total_tokens || 0 : (json.prompt_eval_count || 0) + (json.eval_count || 0);
  try { return { data: JSON.parse(content || ''), error: null, tokens }; } catch (e) { return { data: null, error: 'Invalid JSON from the model', tokens }; }
}

const v = $('Validate request').first().json;
const selected = $('Select evidence').all().map((i) => i.json);
const today = new Date().toISOString().slice(0, 10);

// Dates are compared here, in code, and marked in the excerpts: small models get date arithmetic wrong.
const MONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december'];
const mark = (iso) => (iso < today ? ' [before the analysis date]' : iso > today ? ' [after the analysis date]' : ' [same day as the analysis date]');
const pad = (n) => String(n).padStart(2, '0');
function markDates(text) {
  return text
    .replace(/\b(\d{1,2}) (January|February|March|April|May|June|July|August|September|October|November|December) (\d{4})\b/gi,
      (m, d, mon, y) => m + mark(`${y}-${pad(MONTHS.indexOf(mon.toLowerCase()) + 1)}-${pad(d)}`))
    .replace(/\b(\d{4})-(\d{2})-(\d{2})\b/g, (m) => m + mark(m));
}

const schema = {
  type: 'object',
  properties: {
    status: { type: 'string', enum: ['pass', 'fail', 'unclear', 'not_applicable'] },
    confidence: { type: 'number' },
    explanation: { type: 'string' },
    evidence: { type: 'array', items: { type: 'object', properties: { chunkId: { type: 'string' }, quote: { type: 'string' } }, required: ['chunkId', 'quote'] } },
    kbReferences: { type: 'array', items: { type: 'string' } },
    suggestion: { type: 'string' },
  },
  required: ['status', 'confidence', 'explanation', 'evidence', 'kbReferences', 'suggestion'],
};

const system = `You are a meticulous Rwanda FDA reviewer. You evaluate ONE rule at a time against excerpts from an applicant's submission.
Today's date (the analysis date) is ${today}. Every date in the excerpts is followed by a mark such as [before the analysis date] or [after the analysis date]; rely on these marks for validity and expiry checks instead of comparing dates yourself. Do not include the marks in quotes.

Decide the status:
- "pass": the SUBMISSION EXCERPTS clearly show the rule is met.
- "fail": the SUBMISSION EXCERPTS clearly show the rule is not met, or contain something that contradicts it.
- "unclear": the excerpts do not contain enough information to decide. The excerpts are only part of the submission, so missing information means "unclear", not "fail".
- "not_applicable": the excerpts show the rule does not apply to this product.

Rules for your answer:
- Base the decision only on the SUBMISSION EXCERPTS. KNOWLEDGE BASE excerpts (guidelines, templates, references) explain how to interpret the rule; they are never evidence that the submission complies. A TEMPLATE shows the structure a document is expected to follow.
- For "pass" or "fail", add evidence items. chunkId must be an S-id shown in the excerpts. If the rule compares documents (for example the label with the application form), quote EACH of them; if one of them says nothing on the point, the status is "fail" or "unclear", never "pass". quote must be copied word for word from that excerpt, at most 30 words, preferably one continuous passage.
- kbReferences: the K-ids you relied on, or an empty list.
- explanation: 1 to 3 plain sentences a human reviewer can check.
- suggestion: for "fail" or "unclear", one sentence telling the applicant what to provide or correct; otherwise an empty string.
- confidence: a number between 0 and 1.
Respond with JSON only.`;

const where = (name, page) => `${name}${page ? ', page ' + page : ''}`;
return $input.all().map((item) => {
  const row = item.json;
  const r = selected.find((s) => s.ruleCode === row.rule_code);
  const kb = Array.isArray(row.kb) ? row.kb : (typeof row.kb === 'string' ? JSON.parse(row.kb) : []);
  const kbText = kb.length ? kb.map((k) => `[${k.id}] ${k.kind.toUpperCase()}: ${where(k.title, k.page)}\n${k.text}`).join('\n\n') : '(none)';
  const evText = r.evidence.map((e) => `[${e.id}] (${e.requirementId}: ${where(e.file, e.page)})\n${markDates(e.text)}`).join('\n\n');
  const user = [
    `RULE ${r.ruleCode} (severity: ${r.severity})`, r.rule,
    r.guidance ? `Reviewer guidance: ${r.guidance}` : '',
    `Product type: ${v.productType}. Application: ${v.applicationRef}.`,
    '', 'KNOWLEDGE BASE:', kbText, '', 'SUBMISSION EXCERPTS:', evText,
  ].join('\n');
  return {
    json: {
      ruleCode: r.ruleCode, rule: r.rule, severity: r.severity, requirementIds: r.requirementIds, version: r.version, use: r.use,
      evidence: r.evidence, kb: kb.map(({ id, title, source_key, kind, page }) => ({ id, title, sourceKey: source_key, kind, page })),
      request: llmRequest(v.config, system, user, schema, 'rule_finding'),
    },
  };
});

// LLM request and response helpers, shared by every node that talks to the model.
// OpenAI uses strict JSON-schema output; Ollama uses its "format" option.
function strictSchema(s) {
  // OpenAI strict mode: every object lists all its properties as required and allows no others.
  if (s && s.type === 'object') return { ...s, additionalProperties: false, required: Object.keys(s.properties), properties: Object.fromEntries(Object.entries(s.properties).map(([k, v]) => [k, strictSchema(v)])) };
  if (s && s.type === 'array') return { ...s, items: strictSchema(s.items) };
  return s;
}
function llmRequest(config, system, user, schema, name) {
  const messages = [{ role: 'system', content: system }, { role: 'user', content: user }];
  if (config.llmProvider === 'openai') {
    return { model: config.llmModel, temperature: 0, messages, response_format: { type: 'json_schema', json_schema: { name, strict: true, schema: strictSchema(schema) } } };
  }
  return { model: config.llmModel, stream: false, format: schema, options: { temperature: 0, num_ctx: 8192 }, messages };
}
// Returns { data, error, tokens } from either provider's response item.
function llmResult(json) {
  if (json.error) return { data: null, error: String(json.error.message || json.error), tokens: 0 };
  const content = json.choices ? json.choices[0] && json.choices[0].message && json.choices[0].message.content : json.message && json.message.content;
  const tokens = json.usage ? json.usage.total_tokens || 0 : (json.prompt_eval_count || 0) + (json.eval_count || 0);
  try { return { data: JSON.parse(content || ''), error: null, tokens }; } catch (e) { return { data: null, error: 'Invalid JSON from the model', tokens }; }
}

const prompts = $('Build prompts').all().map((i) => i.json);
// Quotes are compared on words and numbers only, so "80.00-125.00%" matches "80.00-125.00", and the date
// marks added in "Build prompts" are ignored. A quote must still appear in the excerpt word for word.
const norm = (s) => String(s || '').replace(/\s*\[(before|after|same day as) the analysis date\]/gi, '')
  .toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g, ' ').trim();
const STATUSES = ['pass', 'fail', 'unclear', 'not_applicable'];
// A quote may skip words with "..." or "…"; every part must then appear in the excerpt, in order.
function quoteFound(quote, text) {
  const t = norm(text);
  let from = 0;
  const parts = String(quote || '').split(/\.{3}|…/).map(norm).filter(Boolean);
  if (!parts.length) return false;
  for (const p of parts) { const at = t.indexOf(p, from); if (at < 0) return false; from = at + p.length; }
  return true;
}

let tokens = 0;
const findings = $input.all().map((item, i) => {
  const p = prompts[i];
  const base = { ruleCode: p.ruleCode, rule: p.rule, severity: p.severity, requirementIds: p.requirementIds, ruleVersion: p.version };
  const out = llmResult(item.json);
  tokens += out.tokens;
  const r = out.data;
  if (!r || !STATUSES.includes(r.status)) {
    return { ...base, status: 'unclear', confidence: 0, explanation: 'The model output could not be used; manual review needed.', suggestion: '', evidence: [], kbReferences: [],
      checks: { parsed: false, notes: [out.error || 'Unexpected answer from the model'] } };
  }
  // Every quote must really exist in the excerpt the model cited.
  const byId = Object.fromEntries(p.evidence.map((e) => [e.id, e]));
  const evidence = (r.evidence || []).map((ev) => {
    const src = byId[ev.chunkId];
    return { chunkId: ev.chunkId, requirementId: src ? src.requirementId : null, document: src ? src.file : null, page: src ? src.page : null,
      quote: ev.quote, verified: !!src && quoteFound(ev.quote, src.text) };
  });
  const notes = [];
  let status = r.status;
  if ((status === 'pass' || status === 'fail') && !evidence.some((e) => e.verified)) {
    notes.push(`Model answered "${status}" but no quote could be verified in the submission; downgraded to "unclear".`);
    status = 'unclear';
  }
  // A rule that compares documents only passes with a verified quote from each document it was checked against.
  if (status === 'pass' && p.use.length > 1) {
    const quoted = new Set(evidence.filter((e) => e.verified).map((e) => e.requirementId));
    const missing = p.use.filter((id) => !quoted.has(id));
    if (missing.length) {
      notes.push(`Model answered "pass" without quoting ${missing.join(', ')}; a comparison needs evidence from every document. Downgraded to "unclear".`);
      status = 'unclear';
    }
  }
  const kbById = Object.fromEntries(p.kb.map((k) => [k.id, k]));
  return {
    ...base, status, confidence: Math.max(0, Math.min(1, Number(r.confidence) || 0)), explanation: r.explanation || '',
    suggestion: status === 'fail' || status === 'unclear' ? String(r.suggestion || '') : '',
    evidence, kbReferences: (r.kbReferences || []).filter((id) => kbById[id]).map((id) => kbById[id]),
    checks: { parsed: true, notes },
  };
});
// Every call failing means a setup problem (wrong key, no credit, model down), not unclear rules: fail the run.
const failed = findings.filter((f) => !f.checks.parsed);
if (findings.length && failed.length === findings.length) throw new Error(`Every LLM call failed. First error: ${failed[0].checks.notes[0]}`);
return [{ json: { findings, tokens } }];

const v = $('Validate request').first().json;
const analysisId = $('Create analysis record').first().json.id;
const { documents } = $('Split into chunks').first().json;
const { skipped } = $('Scope rules').first().json;
const findings = $input.first().json.findings || [];   // empty when no rule applied
const tokens = $input.first().json.tokens || 0;

const count = (s) => findings.filter((f) => f.status === s).length;
const counts = { pass: count('pass'), fail: count('fail'), unclear: count('unclear'), not_applicable: count('not_applicable'), evaluated: findings.length, skipped: skipped.length };
let verdict = 'compliant';
if (findings.some((f) => f.status === 'fail' && ['critical', 'major'].includes(f.severity))) verdict = 'non_compliant';
else if (counts.fail || counts.unclear || !findings.length) verdict = 'needs_review';

const order = { fail: 0, unclear: 1, pass: 2, not_applicable: 3 };
const sev = { critical: 0, major: 1, minor: 2 };
const result = {
  analysisId, status: 'completed', applicationRef: v.applicationRef, productType: v.productType,
  overall: { verdict, counts },
  summary: `${counts.fail} of ${counts.evaluated} rules failed; ${counts.unclear} unclear; ${counts.pass} passed; ${counts.skipped} not evaluated.`,
  findings: [...findings].sort((a, b) => order[a.status] - order[b.status] || sev[a.severity] - sev[b.severity]),
  skipped,
  documents,
  trace: {
    embedModel: v.config.embedModel, llmProvider: v.config.llmProvider, llmModel: v.config.llmModel, llmTokens: tokens,
    ruleVersions: Object.fromEntries([...findings, ...skipped].map((f) => [f.ruleCode, f.ruleVersion ?? f.version])),
    analyzedAt: new Date().toISOString(),
  },
};
return [{ json: { analysisId, resultJson: JSON.stringify(result) } }];

parameters.query:
UPDATE analyses SET status = 'completed', result = $1::jsonb, finished_at = now()
WHERE id = $2::uuid
RETURNING id, COALESCE(callback_url, '') AS callback_url;
